insert into public.skills (id, slug, name, stage, description, what_good_sounds_like, position) values ('2019f517-682c-502e-9ffa-9b55d1eaaa5a', 'approach', 'Approach and opener', 'door', 'First 10 seconds: body language, intro, reason for being there.', 'Steps back from the door, smiles, says who they are and why they''re on the street in one breath.', 0) on conflict do nothing;
insert into public.skills (id, slug, name, stage, description, what_good_sounds_like, position) values ('4fd69b9a-f536-51f0-b1e3-e14da339b7a8', 'pattern-interrupt', 'Pattern interrupt', 'door', 'Breaking the homeowner''s autopilot ''no'' with a real question.', 'Asks a specific, honest question about the homeowner''s situation instead of a pitch.', 1) on conflict do nothing;
insert into public.skills (id, slug, name, stage, description, what_good_sounds_like, position) values ('ba0b90fe-435f-5e31-b92e-0a154409cf0b', 'tonality', 'Tonality and pace', 'door', 'Calm, confident, downward inflection; matches the homeowner''s energy.', 'Sounds relaxed and certain, never rushed, never pleading.', 2) on conflict do nothing;
insert into public.skills (id, slug, name, stage, description, what_good_sounds_like, position) values ('9822e29d-98ce-5a17-a6c5-3befcce63f41', 'bill-ask', 'Getting the bill', 'door', 'Asking for the electric bill with a clear reason and making it easy.', 'Explains why the bill matters and offers the easiest way to share it.', 3) on conflict do nothing;
insert into public.skills (id, slug, name, stage, description, what_good_sounds_like, position) values ('e3d377e8-9873-5559-91bb-71aa59f559fb', 'qualifying', 'Qualifying', 'door', 'Homeowner, decision makers, roof, bill size, timing.', 'Confirms the basics quickly and politely moves on when someone doesn''t qualify.', 4) on conflict do nothing;
insert into public.skills (id, slug, name, stage, description, what_good_sounds_like, position) values ('a4669ec5-8999-5a6b-8e4f-78a012778958', 'objection-handling', 'Smoke screens and objections', 'door', 'Acknowledge, question, redirect.', 'Agrees first, asks one curious question, gives one honest reason to keep talking.', 5) on conflict do nothing;
insert into public.skills (id, slug, name, stage, description, what_good_sounds_like, position) values ('fd9b5b1c-827a-5094-9847-d607a148ded9', 'setting', 'Setting the appointment', 'door', 'Both decision makers, a specific time, confirmed details.', 'Offers two specific times, confirms both decision makers and contact details, sets expectations.', 6) on conflict do nothing;
insert into public.skills (id, slug, name, stage, description, what_good_sounds_like, position) values ('25c70823-2a0d-57a6-b6f4-2f60bfe386ac', 'discovery', 'Discovery', 'table', 'Uncovering why the homeowner would actually want to change.', 'Asks open questions and lets the homeowner talk about their bill and their goals.', 7) on conflict do nothing;
insert into public.skills (id, slug, name, stage, description, what_good_sounds_like, position) values ('38c3ce1e-595a-54d4-81f4-9ecf06f86908', 'building-value', 'Building value', 'table', 'Connecting the offer to what the homeowner said they care about.', 'Ties every benefit back to something the homeowner said in their own words.', 8) on conflict do nothing;
insert into public.skills (id, slug, name, stage, description, what_good_sounds_like, position) values ('f7bea4ed-1464-5571-8bf1-1d60fa24fbe6', 'closing', 'Closing and next steps', 'table', 'Asking for the decision and making the next step clear.', 'Asks directly, stays quiet, and handles the answer calmly.', 9) on conflict do nothing;
insert into public.skills (id, slug, name, stage, description, what_good_sounds_like, position) values ('bda98b77-1b39-54bf-90a9-25c8c1f840e9', 'resilience', 'Resilience', 'mindset', 'Staying steady after rejection and finishing the plan.', 'Treats each no as data, resets fast, knocks the next door with the same energy.', 10) on conflict do nothing;
insert into public.skills (id, slug, name, stage, description, what_good_sounds_like, position) values ('49e58381-ea53-5e45-8966-d13bf1557caf', 'honesty', 'Honesty and compliance', 'compliance', 'Never misleading the homeowner about who we are or what they''ll get.', 'Says clearly who they are and never promises specific savings or ''free'' anything.', 11) on conflict do nothing;
insert into public.personas (id, slug, name, setting, difficulty, backstory, opening_line, objections, success_condition, start_trust, published) values ('a32bdee9-d100-53cc-b9e3-b9d7316010ca', 'busy-brenda', 'Busy Brenda', 'door', 1, 'Mom of three in a Corona tract home. It''s 5:40pm, dinner is on the stove, kids are loud. Her summer bills hit about $380 and she complains about them to her sister, but she has never looked at solar.', 'Hi—sorry, we''re in the middle of dinner. What is it?', '["I''m busy right now", "We''re not interested", "Can you just leave a flyer?"]'::jsonb, 'giving you a photo of her latest electric bill or a time to come back when her husband is home', 4, true) on conflict do nothing;
insert into public.personas (id, slug, name, setting, difficulty, backstory, opening_line, objections, success_condition, start_trust, published) values ('1607e918-6e40-5aed-b3b0-f432e10c0e50', 'diane-spouse', 'Diane, ''my husband handles that''', 'door', 2, 'Retired school teacher in Riverside. Friendly but defers every money decision to her husband Ray, who gets home at 6. Their bill is around $250 and Ray grumbles about it.', 'Oh hello there. Can I help you?', '["My husband handles all the bills", "He''d have to be here", "We''re not doing anything without him"]'::jsonb, 'an appointment at a specific time when both she and Ray will be home', 5, true) on conflict do nothing;
insert into public.personas (id, slug, name, setting, difficulty, backstory, opening_line, objections, success_condition, start_trust, published) values ('093d2cdf-2095-5493-885c-7e769137dc32', 'skeptic-steve', 'Skeptic Steve', 'door', 3, 'Contractor in Temecula. His neighbor signed a solar deal with another company two years ago and says the savings never showed up. Steve assumes every solar rep is a scammer. His bill is $420 in summer.', 'Let me guess. Solar? Yeah, no. My neighbor got burned.', '["Solar''s a scam", "My neighbor got burned", "You guys all say the same thing", "Just leave me your card"]'::jsonb, 'agreeing to show you his bill and let someone walk through real numbers with no pressure', 3, true) on conflict do nothing;
insert into public.personas (id, slug, name, setting, difficulty, backstory, opening_line, objections, success_condition, start_trust, published) values ('45619e36-2838-5ad3-bcdb-c8f6661be170', 'tom-maria', 'Tom and Maria, ''we need to think about it''', 'table', 3, 'Young couple in Menifee, two kids, both work. They liked the presentation but money feels tight and Maria is nervous about committing. The real worry is whether the payment is truly lower than their bill.', 'Okay, that all makes sense. We just like to sleep on big decisions.', '["We need to think about it", "We want to get other quotes", "Can you just email us the numbers?"]'::jsonb, 'the real concern coming out and either a decision or a firm follow-up time with both of them', 5, true) on conflict do nothing;
insert into public.personas (id, slug, name, setting, difficulty, backstory, opening_line, objections, success_condition, start_trust, published) values ('d6348f9d-0b3f-5d12-bec7-e5558f033435', 'numbers-nate', 'Numbers Nate', 'table', 4, 'Engineer in Irvine with a spreadsheet open. He checks every claim, asks about rate escalators, roof age, panel degradation and what happens if he moves in five years.', 'Before you start, I''ve already modeled this. Show me your assumptions.', '["Your savings assumptions are optimistic", "What''s the escalator?", "What if I sell the house in 5 years?", "My roof is 14 years old"]'::jsonb, 'getting straight, honest answers he can check and agreeing to move forward or to a specific next step', 4, true) on conflict do nothing;
insert into public.tracks (id, slug, name, rep_type, description, total_days, published) values ('c94bfb53-9f60-542b-866f-41d3bec2590f', 'new-setter', 'New Setter', 'setter', 'Your first 60 days, from zero to a consistent, appointment-setting setter.', 60, true) on conflict do nothing;
insert into public.quizzes (id, title, kind, pass_pct, published) values ('b31be9fe-80fb-582a-ac59-a4dd9c61840b', 'Week 1 assessment', 'assessment', 80, true) on conflict do nothing;
insert into public.quiz_questions (id, quiz_id, position, prompt, qtype, options, correct, explanation, skill_slug) values ('0cc5ef66-063f-53be-8890-1eb37399ade5', 'b31be9fe-80fb-582a-ac59-a4dd9c61840b', 1, 'Which of these is never OK to say at the door?', 'single', '["''I''m with Twelve.''", "''We''re with your utility company.''", "''Have your bills gone up?''", "''Mind if I look at your bill?''"]'::jsonb, '1'::jsonb, 'Never imply you''re the utility.', 'honesty') on conflict do nothing;
insert into public.quiz_questions (id, quiz_id, position, prompt, qtype, options, correct, explanation, skill_slug) values ('1846a2ba-9d87-5632-b1ea-daa75e5a1bff', 'b31be9fe-80fb-582a-ac59-a4dd9c61840b', 2, 'The five parts of a door, in order:', 'single', '["Ask, hook, intro, reason, interrupt", "Intro, reason, interrupt, hook, ask", "Hook, ask, intro, interrupt, reason", "Reason, intro, ask, hook, interrupt"]'::jsonb, '1'::jsonb, 'Intro, reason, interrupt, hook, ask.', 'approach') on conflict do nothing;
insert into public.quiz_questions (id, quiz_id, position, prompt, qtype, options, correct, explanation, skill_slug) values ('c03836ea-e46f-538c-8a1d-0f8b68a28ad9', 'b31be9fe-80fb-582a-ac59-a4dd9c61840b', 3, 'Why do we want both decision makers at the appointment?', 'single', '["It''s a legal requirement", "Appointments with one decision maker rarely close", "Closers prefer crowds", "It''s faster"]'::jsonb, '1'::jsonb, 'One decision maker usually means ''I need to talk to my spouse.''', 'setting') on conflict do nothing;
insert into public.quiz_questions (id, quiz_id, position, prompt, qtype, options, correct, explanation, skill_slug) values ('34680c76-3a2e-5c4f-9eb3-5c95f34f94c8', 'b31be9fe-80fb-582a-ac59-a4dd9c61840b', 4, 'A smoke screen is…', 'single', '["A real reason they can''t go solar", "A reflex response like ''not interested''", "A signed contract", "A bad roof"]'::jsonb, '1'::jsonb, 'Smoke screens are reflexes, not decisions.', 'objection-handling') on conflict do nothing;
insert into public.quiz_questions (id, quiz_id, position, prompt, qtype, options, correct, explanation, skill_slug) values ('33a263bd-d93a-5d21-a2fb-c9fd259f479b', 'b31be9fe-80fb-582a-ac59-a4dd9c61840b', 5, 'Good tonality at the door sounds…', 'single', '["Fast and excited", "Calm and certain, ending statements down", "Like a question", "Very loud"]'::jsonb, '1'::jsonb, 'Calm, certain, downward inflection.', 'tonality') on conflict do nothing;
insert into public.quiz_questions (id, quiz_id, position, prompt, qtype, options, correct, explanation, skill_slug) values ('8d5a3075-b4e3-5329-9456-39ffd4bc12c6', 'b31be9fe-80fb-582a-ac59-a4dd9c61840b', 6, 'What should you do before uploading a real conversation?', 'single', '["Nothing", "Make sure the homeowner agreed to be recorded", "Delete the first minute", "Ask your closer"]'::jsonb, '1'::jsonb, 'Everyone in the conversation must agree to be recorded.', 'honesty') on conflict do nothing;
